    awaitNative([&]{auto s=client.status();return s["intentId"].toString()=="design:unavailable" && s["error"].toString().contains("Changed source") && !(bool)s["playing"] && !(bool)s["pendingPlayback"];},"Unavailable Designer source retains transport ownership and actionable error");client.stop();
    auto *report=new juce::DynamicObject();report->setProperty("checks",checks);report->setProperty("directory",out.getFullPathName());report->setProperty("renderMaxAbsoluteError",renderDelta);report->setProperty("streamMaxAbsoluteError",streamDelta);report->setProperty("devicePreMonitorMaxAbsoluteError",deviceDelta);report->setProperty("deviceRateChecks",rateChecks);report->setProperty("nativeWallMs",sp::monotonicMs()-started);report->setProperty("nativeStatus",final);report->setProperty("nativeRunningStatus",running);report->setProperty("timestamp",juce::Time::getCurrentTime().toISO8601(true));check(parent.getChildFile("latest.json").replaceWithText(juce::JSON::toString(juce::var(report),true)),"Evidence written");std::cout<<"Designer checks passed: "<<checks<<"\n";
