void prepareDesignWorkload(const juce::File &folder)
{
    if(folder.exists())throw std::runtime_error("Use a new owned workload directory");check(folder.createDirectory().wasOk(),"Create workload");
    auto a=fixture(folder,44100,1,44100*40),b=fixture(folder,48000,4,48000*40),c=fixture(folder,96000,2,96000*40);
    sp::DesignDocument d;d.name="Eight layers - mixed rates and stock inserts";d.original.masterDb=-6;d.renderSettings.tailSeconds=1;
    for(int i=0;i<8;++i){auto l=sp::makeDesignLayer(i%3==0 ? a : i%3==1 ? b : c,0,-1,true);l.gainDb=-24;l.rate=i%2 ? .875 : 1;l.reverse=i%3==1;l.region.auditionPair=i%3==1 ? 1 : 0;l.fadeIn=480;l.fadeOut=960;l.inserts.stock={sp::makeStockEffect("filter"),sp::makeStockEffect("delay"),sp::makeStockEffect("reverb")};d.original.layers.push_back(l);}
    d.original.inserts.stock={sp::makeStockEffect("filter"),sp::makeStockEffect("reverb")};d.selectedLayer=d.original.layers[0].id;sp::saveDesignAtomic(folder.getChildFile("workload.soundplus"),d);std::cout<<"Prepared eight-layer 40-second sources\n";
}
void interruptDesignOperation(bool render,const juce::File &target,const juce::File &snapshot,const juce::File &checkpoint)
{
    auto d=sp::loadDesign(snapshot);int calls=0;auto cancel=[&]{if(++calls>=(render ? 3 : 2)){if(!checkpoint.replaceWithText("Staged; terminate this isolated test process"))throw std::runtime_error("Checkpoint write failed");for(;;)std::this_thread::sleep_for(std::chrono::seconds(1));}return false;};
    if(render)sp::renderDesign(d,target,d.renderSettings,cancel,[](double){});else sp::saveDesignAtomic(target,d,cancel);
}
